// n8n Code node -- "Mapear campos del formulario"
// The Form Trigger node's output keys depend on the exact field labels as
// n8n stores them (can vary by version/locale), so instead of hardcoding
// exact key names, find each field by a substring of its label. This way
// the rest of the flow (which expects snake_case keys) doesn't break if
// n8n's internal key format differs from what you'd guess.

const raw = $input.first().json;

function findField(substrings) {
  for (const [key, value] of Object.entries(raw)) {
    const k = key.toLowerCase();
    if (substrings.some((s) => k.includes(s))) return value;
  }
  return null;
}

return [{
  json: {
    company_name: findField(["nombre de la empresa", "company_name"]),
    ruc: findField(["ruc"]),
    whatsapp_phone: findField(["whatsapp"]),
    departments: findField(["departamento"]) || "",
    business_description: findField(["dedica", "ofrecen", "business_description"]),
    min_amount: findField(["minimo", "min_amount"]),
    max_amount: findField(["maximo", "max_amount"]),
  },
}];

// n8n Code node -- "Parsear respuesta LLM"
// Input: one item with the OpenAI node's output (message text) plus the
// original form fields (company_name, ruc, whatsapp_phone, departments,
// business_description, min_amount, max_amount) passed through from before.
// Output: one item ready for the Postgres "Insertar mype_profiles" node.

const item = $input.first().json;

// The OpenAI node (Message a Model) puts the model's reply text here;
// adjust this path if your n8n version names the field differently
// (check the node's output panel -- look for "content" or "text").
const raw = item.message?.content ?? item.content ?? item.text ?? "";

const match = raw.match(/\{[\s\S]*\}/);
if (!match) {
  throw new Error("No se encontro JSON en la respuesta del LLM: " + raw);
}

const parsed = JSON.parse(match[0]);
const families = Array.isArray(parsed.families) ? parsed.families : [];

const departments = (item.departments || "")
  .split(",")
  .map((d) => d.trim().toUpperCase())
  .filter(Boolean);

return [{
  json: {
    company_name: item.company_name,
    ruc: item.ruc,
    whatsapp_phone: item.whatsapp_phone,
    departments, // plain JS array -- the Postgres node serializes this correctly for a TEXT[] column
    business_description: item.business_description,
    unspsc_families: families, // plain JS array, same reason
    mapping_reasoning: parsed.reasoning || null,
    min_amount: item.min_amount || null,
    max_amount: item.max_amount || null,
    status: "pending_review",
  },
}];
